11	// index.ts; imported here for internal variant resolution.
12	import { TooltipVariant } from "./constants";
13	
14	const Tooltip = TooltipPrimitive.Root;
15	const TooltipTrigger = TooltipPrimitive.Trigger;
16	
17	const tooltipThemeClass = {
18	  inverse: "ds-tooltip-inverse-theme",
19	  matching: "ds-tooltip-matching-theme",
20	} as const;
21	
22	const TooltipProvider = ({
23	  delayDuration = 250,
24	  ...props
25	}: ComponentPropsWithoutRef<typeof TooltipPrimitive.Provider>) => (
26	  <TooltipPrimitive.Provider delayDuration={delayDuration} {...props} />
27	);
28	
29	export interface TooltipContentProps extends ComponentPropsWithoutRef<
30	  typeof TooltipPrimitive.Content
31	> {
32	  variant?: TooltipVariant;
33	  themeInverse?: boolean;
34	  portal?: boolean;
35	  portalProps?: ComponentPropsWithoutRef<typeof TooltipPrimitive.Portal>;
36	}
