39	  ComponentRef<typeof TooltipPrimitive.Content>,
40	  TooltipContentProps
41	>(
42	  (
43	    {
44	      className,
45	      variant = TooltipVariant.simple,
46	      themeInverse = true,
47	      portal = true,
48	      portalProps,
49	      sideOffset = 6,
50	      children,
51	      ...props
52	    },
53	    ref,
