62	          "data-[state=instant-open]:animate-in data-[state=instant-open]:fade-in-0 data-[state=instant-open]:zoom-in-95",
63	          "data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
64	          "ds-motion-overlay",
65	          tooltipThemeClass[themeInverse ? "inverse" : "matching"],
66	          variant === TooltipVariant.simple &&
