import * as PopoverPrimitive from "@radix-ui/react-popover";
import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ComponentRef,
} from "react";
import { cn } from "../../utils/cn";

const Popover = PopoverPrimitive.Root;
const PopoverTrigger = PopoverPrimitive.Trigger;
const PopoverAnchor = PopoverPrimitive.Anchor;
const PopoverPortal = PopoverPrimitive.Portal;
const PopoverClose = PopoverPrimitive.Close;

export type PopoverContentProps = ComponentPropsWithoutRef<
  typeof PopoverPrimitive.Content
> & {
  /** Render into a portal. Default true; set false to keep the panel inline. */
  portal?: boolean;
  portalProps?: ComponentPropsWithoutRef<typeof PopoverPrimitive.Portal>;
};

const PopoverContent = forwardRef<
  ComponentRef<typeof PopoverPrimitive.Content>,
  PopoverContentProps
>(
  (
    {
      className,
      align = "start",
      sideOffset = 6,
      collisionPadding = 8,
      portal = true,
      portalProps,
      ...props
    },
    ref,
  ) => {
    const content = (
      <PopoverPrimitive.Content
        ref={ref}
        align={align}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "z-50 overflow-hidden rounded-normal",
          "border border-solid border-border-popovers bg-modal-surface shadow-menu",
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          "data-[state=open]:fade-in-0 data-[state=closed]:fade-out-0",
          "data-[state=open]:zoom-in-95 data-[state=closed]:zoom-out-95",
          "ds-motion-overlay",
          "ds-radix-popover-content-origin",
          className,
        )}
        {...props}
      />
    );

    return portal ? (
      <PopoverPrimitive.Portal {...portalProps}>{content}</PopoverPrimitive.Portal>
    ) : (
      content
    );
  },
);
PopoverContent.displayName = "PopoverContent";

export {
  Popover,
  PopoverAnchor,
  PopoverClose,
  PopoverContent,
  PopoverPortal,
  PopoverTrigger,
};
```

### Popover Barrel Export Pattern
**File:** `/src/components/Popover/index.ts`

```typescript
export {
  Popover,
  PopoverAnchor,
  PopoverClose,
  PopoverContent,
  PopoverPortal,
  PopoverTrigger,
} from "./Popover";
export type { PopoverContentProps } from "./Popover";
```

### Key Motion & Animation Patterns

The design system uses **Tailwind CSS animate plugin** with **data-state attributes** for Radix components:

**Animation Classes Structure (from Popover):**
- `data-[state=open]:animate-in` / `data-[state=closed]:animate-out` — triggers animation direction
- `data-[state=open]:fade-in-0` / `data-[state=closed]:fade-out-0` — fade amount (0 = 0% opacity)
- `data-[state=open]:zoom-in-95` / `data-[state=closed]:zoom-out-95` — zoom scale (95 = 95%)
- `ds-motion-overlay` — applies timing from design tokens (fast in/out for small overlays)

**Motion Timing Classes (from dooph-component-tokens.css):**
- `.ds-motion-overlay` — small overlays (menu, tooltip, popover): `var(--ui-motion-duration-fast)` + `var(--ui-motion-ease-enter)` on open
- `.ds-motion-overlay-dialog` — modal: `var(--ui-motion-duration-base)` in, fast out
- `.ds-motion-overlay-sheet` — sheet: slow in, base out
- All timing lives on the motion scale, so reduced-motion query collapses durations automatically

**Key @keyframes exist for:**
- `ds-spinner-dash`, `ds-shape-morph-*`, `ds-roll-*`, `ds-fade-change-*`, `ds-rolling-digits-*`, `ds-underline-wipe`
- No collapsible-specific keyframes exist yet

