330	        {/* Keeps multi-node children one inline run, so the root's gap sits
331	         * only between the label and the chevron. Slottable marks the asChild target. */}
332	        <Slottable child={children}>{(child) => <span>{child}</span>}</Slottable>
333	        <ChevronDownIcon
334	          size={
335	            size === TextDropdownSize.sm ? IconSize.sm : IconSize.rg
336	          }
337	        />
338	      </BaseText>
339	    );
340	  },
341	);
342	TextDropdownTriggerBase.displayName = "TextDropdownTrigger";
343	
