import * as CollapsiblePrimitive from "@radix-ui/react-collapsible";
import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ComponentRef,
} from "react";
import { cn } from "../../utils/cn";
import { ButtonText } from "../Text";
import { ChevronDownIcon, IconSize } from "../Icons";

const Collapsible = CollapsiblePrimitive.Root;

/* CollapsibleTrigger */

export type CollapsibleTriggerProps = ComponentPropsWithoutRef<
  typeof CollapsiblePrimitive.Trigger
>;

/**
 * A trigger that shows its children as a label with a chevron that flips when the collapsible is open.
 *
 * `className` and `ref` land on the trigger root.
 */
const CollapsibleTrigger = forwardRef<
  ComponentRef<typeof CollapsiblePrimitive.Trigger>,
  CollapsibleTriggerProps
>(({ className, children, ...props }, ref) => (
  <CollapsiblePrimitive.Trigger
